<?php
namespace App\Http\Controllers;
use App\Models\Tenant; use App\Services\PosUserDirectoryClient; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class UserDirectoryController extends Controller
{
    public function index(Request $request, PosUserDirectoryClient $client): View { $companies=Tenant::where('status','active')->orderBy('name')->get(); $selectedCompanyId=$request->integer('company_id'); $selectedCompanies=$selectedCompanyId ? $companies->where('id',$selectedCompanyId) : $companies; $users=[]; foreach($selectedCompanies as $company){try{foreach($client->list($company) as $user){$users[]=[...$user,'company'=>$company];}}catch(\Throwable $e){report($e);}} return view('users.index',compact('companies','users','selectedCompanyId')); }
    public function create(): View { return view('users.create',['companies'=>Tenant::where('status','active')->orderBy('name')->get()]); }
    public function store(Request $request, PosUserDirectoryClient $client): RedirectResponse { $data=$request->validate(['company_id'=>['required','exists:companies,id'],'name'=>['required','string','max:255'],'email'=>['required','email'],'is_active'=>['required','boolean']]); $company=Tenant::findOrFail($data['company_id']); try{$client->create($company,collect($data)->except('company_id')->all());return to_route('users.index')->with('success','Usuario creado. Envía el correo de contraseña desde su edición.');}catch(\Throwable $e){return back()->withInput()->withErrors(['email'=>'No se pudo crear en POS: '.$e->getMessage()]);} }
    public function edit(Tenant $company, int $userId, PosUserDirectoryClient $client): View { return view('users.edit',['company'=>$company,'user'=>$client->find($company,$userId)]); }
    public function update(Request $request, Tenant $company, int $userId, PosUserDirectoryClient $client): RedirectResponse { $data=$request->validate(['name'=>['required','string','max:255'],'email'=>['required','email'],'is_active'=>['required','boolean']]); try{$client->update($company,$userId,$data);return back()->with('success','Usuario actualizado en POS.');}catch(\Throwable $e){return back()->withErrors(['email'=>'No se pudo actualizar: '.$e->getMessage()]);} }
    public function sendReset(Tenant $company, int $userId, PosUserDirectoryClient $client): RedirectResponse { try{$client->sendReset($company,$userId);return back()->with('success','Correo para cambio de contraseña enviado.');}catch(\Throwable $e){return back()->withErrors(['email'=>'No se pudo enviar el correo: '.$e->getMessage()]);} }
}
